export type FaqItem = { question: string; answer: string };

export const guideFaqs: Record<string, FaqItem[]> = {

  "personal-injury-claim-time-limit-scotland": [
    { question: "How long do I have to make a personal injury claim in Scotland?", answer: "In Scotland the general time limit is three years from the date of the accident, or from the date of knowledge if you did not immediately know you had suffered a significant injury. Missing this deadline can permanently bar your claim." },
    { question: "What happens if I miss the three-year time limit in Scotland?", answer: "Your claim may become time-barred and the court can refuse to hear it. The court has a limited discretion to allow late claims in exceptional circumstances under section 19A of the Prescription and Limitation (Scotland) Act 1973, but this discretion is not routinely granted. Do not rely on it." },
    { question: "When does the three-year clock start in an industrial disease claim?", answer: "In industrial disease cases the three-year period runs from the date of diagnosis or from the date you first knew your condition was caused by your work, whichever is later. This means claims can be made many years after the original exposure." },
    { question: "What is the time limit for a child's personal injury claim in Scotland?", answer: "For a child, the three-year limitation period does not begin until their sixteenth birthday. In practice, claims can normally be brought up to age 19. A parent can investigate and pursue a claim on a child's behalf before that time." },
    { question: "Does the three-year limit apply to medical negligence claims in Scotland?", answer: "Yes. The three years runs from the date of the negligent act or the date of knowledge — whichever is later. In complex cases, particularly where harm emerged gradually, establishing the correct date of knowledge requires careful analysis." },
    { question: "Can the time limit be extended in Scotland?", answer: "The court has a discretion under section 19A to allow a late action, but this is not automatic. The court weighs the prejudice to both parties, the reason for the delay and the strength of the evidence. Do not plan to rely on this discretion — seek advice as soon as possible." },
  ],

  "evidence-for-personal-injury-claim-scotland": [
    { question: "What evidence do I need for a personal injury claim in Scotland?", answer: "The core evidence is proof of fault (who caused the accident), causation (that the fault caused your specific injury) and loss (the financial and non-financial consequences). This typically means accident scene evidence, medical records, witness statements and financial documents." },
    { question: "How important are photographs in a personal injury claim?", answer: "Very important. Photographs of the scene, the hazard, your injuries and any vehicle or property damage taken as soon as safely possible provide contemporaneous evidence that is difficult to dispute later. Date-stamped images from your phone are widely used in Scottish courts." },
    { question: "Do I need a witness to make a personal injury claim in Scotland?", answer: "Not necessarily, but witnesses significantly strengthen a claim. If you have witness details, record them immediately. CCTV, dashcam and body-camera footage can sometimes substitute for witnesses, particularly in road accident and public-place cases." },
    { question: "Can I use medical records as evidence in my claim?", answer: "Yes. GP, hospital and physiotherapy records documenting your injury, treatment and prognosis are central evidence. Your adviser can request records formally. Consistent entries made at the time of the injury carry more weight than records created later." },
    { question: "What financial evidence should I keep after an accident?", answer: "Keep payslips, bank statements, receipts for treatment, travel and medication, care records showing who helped you and for how long, and any written explanations from your employer of earnings lost. The stronger your financial evidence, the more accurately your claim can be valued." },
    { question: "How long should I preserve evidence after an accident?", answer: "Preserve everything until your claim is fully resolved. Important categories — CCTV, dashcam, physical scene evidence — can disappear within days. Keep all documents and do not repair or dispose of damaged property before its condition is professionally assessed." },
  ],

  "can-i-claim-if-partly-at-fault-scotland": [
    { question: "Can I still claim compensation if I was partly to blame for the accident?", answer: "Yes. Scotland applies contributory negligence, which means your compensation is reduced by the proportion of fault attributed to you, but a claim is not automatically defeated. A 30% reduction still leaves 70% compensation payable." },
    { question: "How does contributory negligence work in Scotland?", answer: "The court or insurer assesses the relative fault of each party as a percentage. If you are found 25% responsible and the other party 75% responsible, your compensation is reduced by 25%. The defender must prove your contribution with evidence, not merely assert it." },
    { question: "What if the insurer says I was mostly at fault?", answer: "An insurer's assertion of high contributory negligence is not a final determination. It must be supported by evidence. Challenge it with independent evidence — CCTV, witnesses, road markings, speed data — and obtain advice before accepting any admission of blame." },
    { question: "Does not wearing a seatbelt mean I can't claim?", answer: "No. Not wearing a seatbelt may reduce compensation for injuries that a seatbelt would have prevented or reduced, but it does not defeat the claim entirely or shift fault for the collision. Any reduction must be justified by medical evidence." },
    { question: "Can I claim if the accident happened at work and I broke a safety rule?", answer: "Possibly. Breaking a safety rule may be raised as contributory negligence, but your employer's responsibility to provide training, supervision and a safe system of work remains. Contributory negligence reduces but does not automatically eliminate a valid claim against an employer." },
    { question: "I was crossing the road when hit by a car — does jaywalking affect my claim?", answer: "Crossing away from a formal crossing point may be raised as contributory negligence, but the driver still has a duty to see and avoid pedestrians. The assessment considers both your conduct and the driver's speed, lookout and ability to avoid the collision." },
  ],

  "what-if-liability-denied-scotland": [
    { question: "What happens if the other side denies liability for my accident in Scotland?", answer: "A liability denial means the other party disputes responsibility. Your claim does not end — you gather and present evidence to establish fault, which may involve witnesses, CCTV, expert reports and court proceedings if necessary." },
    { question: "Can I still win a personal injury claim after liability is denied?", answer: "Yes. Many claims succeed after an initial liability denial. The denial triggers an evidence-gathering phase. Courts decide liability based on the balance of probabilities, meaning you must show it is more likely than not that the other party was at fault." },
    { question: "Why would an insurer deny liability?", answer: "Insurers deny liability where they believe the evidence does not clearly establish fault, where they dispute causation, where there are witness inconsistencies, or simply to put the claimant to proof. A denial is a tactical and legal position, not a final determination." },
    { question: "What evidence can I use to counter a liability denial?", answer: "Dashcam footage, CCTV, independent witnesses, photographs, police reports, accident reconstruction experts, vehicle inspection reports and inspection or maintenance records can all be used. The strength of your evidence is what matters, not the other party's position." },
    { question: "Should I raise court proceedings if liability is denied?", answer: "Court proceedings may be necessary to protect the limitation period and to progress the claim where negotiation fails. Raising proceedings does not mean a hearing is inevitable — many cases settle after proceedings are served." },
    { question: "How long does a disputed liability claim take in Scotland?", answer: "Disputed cases vary considerably. Simple cases may resolve within 12 to 18 months. Complex cases involving expert evidence, multiple parties or serious injuries can take several years. Your adviser should give you a realistic timeline based on your specific circumstances." },
  ],

  "do-i-need-to-go-to-court-scotland": [
    { question: "Will my personal injury claim go to court in Scotland?", answer: "The majority of personal injury claims in Scotland settle without a court hearing. Court proceedings are often raised to protect limitation periods or to progress a stalled negotiation, but most cases resolve by agreement before a hearing takes place." },
    { question: "When would I have to go to court for a personal injury claim?", answer: "A contested hearing becomes more likely where liability is seriously disputed, where the value of the claim cannot be agreed, where there are significant credibility issues, or where the other side makes no reasonable offer. Your adviser will explain if a hearing becomes necessary in your case." },
    { question: "What is the All-Scotland Sheriff Personal Injury Court?", answer: "The All-Scotland Sheriff Personal Injury Court (ASPIC) in Edinburgh handles most Scottish personal injury actions where the sum claimed exceeds £5,000. It has specialist personal injury sheriffs and its own procedural rules designed to resolve cases efficiently." },
    { question: "Is the Scottish court process different from England and Wales?", answer: "Yes. Scotland has a distinct court system with separate procedural rules, different evidence requirements and different judicial terminology. A court-based personal injury claim in Scotland is governed by Scots law and Scottish civil procedure, not English civil procedure rules." },
    { question: "Can I settle my claim without going to court?", answer: "Yes. Most claims settle through negotiation between advisers and insurers. You agree the compensation directly, sign a settlement agreement and receive payment. If proceedings have been raised, they can be withdrawn once settlement is agreed." },
    { question: "How long does a court case take in Scotland?", answer: "Where a hearing is necessary, timescales depend on the complexity of the case and the court's availability. Simple cases may take 12 to 18 months from raising proceedings to a hearing. Complex or multi-expert cases can take considerably longer." },
  ],

  "road-traffic-accident-claims-scotland": [
    { question: "What should I do immediately after a road traffic accident in Scotland?", answer: "Ensure safety first and call 999 if anyone is injured. Exchange names, addresses and insurance details with all drivers. Photograph vehicles, road layout, damage and any injuries. Note the time, location, weather and witnesses. Preserve dashcam footage before it overwrites." },
    { question: "Can I claim if the other driver was uninsured?", answer: "Yes. Claims involving uninsured drivers in Scotland can be made through the Motor Insurers' Bureau Uninsured Drivers' Agreement. You should report the accident to police and keep all evidence including the driver's details and vehicle registration." },
    { question: "How long do I have to make a road traffic accident claim in Scotland?", answer: "Three years from the date of the accident or date of knowledge. CCTV is typically overwritten within days, so investigate and preserve evidence without delay even if you are not ready to proceed immediately." },
    { question: "What compensation can I claim after a road accident in Scotland?", answer: "You can claim for pain, suffering and loss of amenity, lost earnings, treatment and rehabilitation costs, care provided by others, vehicle damage or hire, and other proven financial losses. Future losses are included where the medical evidence supports them." },
    { question: "Does the English whiplash tariff apply to Scottish road accident claims?", answer: "No. Scotland has its own legal system and its own approach to valuing soft-tissue injury claims. The fixed English whiplash tariff regime does not apply in Scotland, where awards are assessed on medical evidence and comparable Scottish judicial awards." },
    { question: "Can I claim if I was a passenger in a vehicle involved in an accident?", answer: "Yes. An innocent passenger can claim against whichever driver or drivers caused the collision, including the driver of their own vehicle. The claim is usually met by the driver's insurer rather than the driver personally." },
  ],

  "whiplash-claims-scotland": [
    { question: "How much compensation will I get for whiplash in Scotland?", answer: "Whiplash compensation in Scotland is assessed on your specific medical evidence, symptom duration, effect on daily life and financial losses — not a fixed tariff. The English whiplash tariff regime does not apply in Scotland. Awards vary significantly depending on severity and persistence of symptoms." },
    { question: "Do whiplash symptoms always appear immediately after an accident?", answer: "No. NHS inform notes that whiplash symptoms can take 24 to 48 hours to develop fully. Delayed onset is normal and does not undermine a genuine claim. See a doctor as soon as symptoms appear and tell them about the accident." },
    { question: "How long does it take for whiplash to heal?", answer: "Most whiplash injuries improve within a few weeks to a few months. More severe cases can last a year or longer and may include persistent neck pain, headaches, cognitive symptoms and psychological effects. Your medical evidence should reflect your actual recovery trajectory." },
    { question: "Can an insurer reject a whiplash claim as not credible?", answer: "Yes. Insurers may challenge claims where the collision was low-speed, where reporting was delayed, or where treatment records are inconsistent. A detailed symptom diary, consistent medical records and honest reporting of pre-existing conditions strengthen your credibility." },
    { question: "Does a previous neck injury affect my whiplash claim?", answer: "A pre-existing condition does not prevent a claim. The question is whether the accident caused a new injury or materially worsened your existing condition. Honest disclosure of prior history, supported by medical records, is a better strategy than concealment." },
    { question: "What evidence should I keep for a whiplash claim?", answer: "Keep the accident report, dashcam footage, GP and physiotherapy records, a dated symptom diary, medication receipts, records of days off work, and any receipts for help with tasks you could not manage. Contemporaneous records made at the time carry the most weight." },
  ],

  "cycling-accident-claims-scotland": [
    { question: "Can I claim compensation after a cycling accident in Scotland?", answer: "Yes, if the accident was caused by another road user's negligence, a road defect, or a failure by a roads authority or occupier. The claim requires evidence of fault, causation and loss, and follows the same legal framework as other personal injury claims in Scotland." },
    { question: "Does not wearing a helmet affect my cycling accident claim?", answer: "Not wearing a helmet does not determine who caused the accident. An insurer may argue that a helmet would have reduced a specific head injury, but this argument is injury-specific and must be supported by medical evidence. It does not defeat the claim entirely." },
    { question: "Can I claim against a driver who passed too close?", answer: "Yes. The Highway Code requires drivers to give cyclists at least 1.5 metres of space when overtaking at speeds up to 30mph. An unsafe pass that causes injury or a fall may ground a claim, supported by cycle camera footage if available." },
    { question: "Can I claim for damage to my bicycle as well as my injuries?", answer: "Yes. A cycling accident claim can include the cost of repairing or replacing your bicycle, damaged cycling equipment, medical treatment, lost earnings, care and pain and suffering. Obtain a professional damage assessment before repairing the bicycle." },
    { question: "What if I fell because of a pothole or road defect?", answer: "You can investigate a claim against the roads authority responsible for maintaining that road. You must establish that the defect existed, that it caused your fall, and that the authority knew or should have known about it. Photograph the defect with a scale object and record its exact location immediately." },
    { question: "How long do I have to claim after a cycling accident?", answer: "Three years from the accident date or date of knowledge. Dashcam and CCTV footage is overwritten quickly, road defects are repaired, and witnesses move on — preserve evidence urgently even if you are not certain whether you will claim." },
  ],

  "motorcycle-accident-claims-scotland": [
    { question: "Can I claim compensation after a motorcycle accident in Scotland?", answer: "Yes. A motorcyclist can claim where another road user, roads authority or other party was negligent. Motorcycle accident claims follow the same legal framework as other road accident claims in Scotland, though evidence of riding conduct and protective equipment may be particularly relevant." },
    { question: "Will insurers try to say I was riding dangerously?", answer: "Insurers often raise a motorcyclist's speed, lane position, protective equipment or road conditions as contributory negligence. These arguments must be supported by evidence. Challenge them with dashcam or helmet camera footage, witness accounts and road scene photographs." },
    { question: "Does not wearing protective clothing reduce my compensation?", answer: "Not wearing armoured clothing or a back protector may be raised as contributory negligence in relation to specific injuries that such clothing might have reduced. Any reduction must be based on medical evidence linking the absence of protection to your actual injuries. It does not defeat the claim." },
    { question: "What if the accident was caused by an animal in the road?", answer: "A claim may lie against the animal's owner if the escape was caused by negligence, or against a roads authority if a known hazard was not addressed. Each case depends on who was responsible for the animal or the road condition. Preserve evidence of the scene." },
    { question: "Can I claim for my motorcycle damage as well as personal injury?", answer: "Yes. A motorcycle accident claim can include the cost of repairs or replacement, protective gear, helmet, leathers, lost earnings, medical treatment and pain and suffering. Retain all receipts and obtain a professional engineering assessment of the vehicle damage." },
    { question: "How long do I have to make a motorcycle accident claim in Scotland?", answer: "Three years from the accident or date of knowledge. Act promptly — helmet cameras and dashcams are overwritten quickly, road surfaces are repaired, and eyewitnesses become harder to locate over time." },
  ],

  "accident-at-work-claim-scotland": [
    { question: "Can I claim against my employer for a work accident in Scotland?", answer: "Yes. Employers have a legal duty under Scots law and health and safety legislation to provide a safe workplace, safe equipment and adequate training. If they breach that duty and you are injured as a result, you may have a valid claim for compensation." },
    { question: "Will claiming against my employer affect my job?", answer: "It is unlawful for an employer to dismiss or penalise you for making a legitimate personal injury claim. Your claim is made against their employers' liability insurer, not against them personally. Many workers successfully pursue claims without any adverse effect on their employment." },
    { question: "What if my employer blames me for the accident?", answer: "Your employer may argue contributory negligence, but they must prove it with evidence. Their duty to provide proper training, supervision and a safe system of work remains, even if you made an error. Contributory negligence reduces rather than eliminates a valid claim." },
    { question: "What if my employer says the risk was obvious?", answer: "Employers cannot simply argue a risk was obvious to escape liability. They are required to assess risks, implement controls, provide training and ensure those controls are followed. An obvious risk that the employer failed to mitigate can still support a claim." },
    { question: "Can I claim if I'm self-employed or work for an agency?", answer: "Possibly. The duty owed depends on who controlled your work and the working environment. Agency workers and subcontractors may have claims against the occupier of premises, the principal employer or both. Seek advice on who the correct defendant is in your specific situation." },
    { question: "How long do I have to make a workplace accident claim in Scotland?", answer: "Three years from the accident date or date of knowledge. Report the accident in the workplace accident book immediately and keep your own copy. Do not assume the employer's internal investigation protects your legal position." },
    { question: "What compensation can I get for a work accident?", answer: "Compensation can include pain and suffering, lost earnings, treatment costs, care provided by others, loss of future earnings or pension if you cannot return to the same work, and other proven financial losses. The amount depends on the severity of your injury and your provable losses." },
  ],

  "construction-accident-claims-scotland": [
    { question: "Who is liable for a construction site accident in Scotland?", answer: "Liability may rest with your employer, the principal contractor, the site occupier, a subcontractor, a plant hire company or a combination. Construction sites have complex legal relationships. The party who controlled the unsafe condition or system of work is usually a key defendant." },
    { question: "Can I claim if I was an agency worker or subcontractor on site?", answer: "Yes. The duty of care on a construction site runs with control of the work and environment, not just employment status. Subcontractors and agency workers injured by the negligence of a principal contractor or site occupier can pursue claims against those parties." },
    { question: "What are the most common construction accident claims in Scotland?", answer: "Falls from height, struck-by incidents involving plant or falling objects, manual handling injuries, scaffolding collapses, electrical accidents and trench or excavation incidents are among the most common categories. Each has specific regulations and evidence requirements." },
    { question: "What health and safety regulations apply to construction sites?", answer: "The Construction (Design and Management) Regulations 2015, the Work at Height Regulations 2005, the Manual Handling Operations Regulations 1992 and the Provision and Use of Work Equipment Regulations 1998 are among the most frequently relevant in Scottish construction claims." },
    { question: "What evidence should I preserve after a construction accident?", answer: "Keep the accident book entry, photograph the hazard and scene, obtain witness details, preserve PPE or defective equipment before it is replaced or repaired, request CCTV from site systems, and keep medical records from your first attendance. Report the accident to your employer and the HSE if RIDDOR-reportable." },
    { question: "How long do I have to claim after a construction accident in Scotland?", answer: "Three years from the accident or date of knowledge. Do not wait for any employer or HSE investigation to conclude — your legal time limit runs independently." },
  ],

  "offshore-injury-claims-scotland": [
    { question: "Can I claim compensation for an injury on an oil rig or offshore platform?", answer: "Yes. Offshore workers have legal rights to claim compensation for injuries caused by employer negligence or breach of statutory duty. The applicable law may be Scots law, English law or international maritime law depending on the platform's location and jurisdiction." },
    { question: "What law applies to offshore injury claims in Scotland?", answer: "Claims involving Scottish Continental Shelf operations or installations in Scottish waters often involve Scots law, but the applicable law depends on the specific location, the contractual arrangements and international conventions. Specialist advice is essential given the jurisdictional complexity." },
    { question: "Does the offshore three-year time limit apply to my claim?", answer: "A three-year limitation period generally applies, but the starting date and the applicable limitation regime depend on the legal jurisdiction governing your claim. Offshore claims require specialist analysis — seek advice promptly rather than assuming you know when the clock started." },
    { question: "Who is responsible for safety on an offshore installation?", answer: "The duty holder — typically the operator — has primary responsibility under the Offshore Installations and Pipeline Works (Management and Administration) Regulations 1995. Employers, contractors and equipment manufacturers may also have duties. Establish the correct defendants early." },
    { question: "Can I claim if I am a contractor rather than an employee offshore?", answer: "Yes. Contractors may have claims against the installation operator, the principal employer or both, depending on who controlled the work. Employment status does not determine liability for health and safety breaches on offshore installations." },
    { question: "What are the most common offshore injury types in Scotland?", answer: "Common categories include falls from height, manual handling injuries, equipment and machinery accidents, fire and explosion incidents, toxic exposure, and helicopter transit accidents. Each requires specific evidence and often expert engineering or medical analysis." },
  ],

  "medical-negligence-what-to-prove-scotland": [
    { question: "What do I need to prove to win a medical negligence claim in Scotland?", answer: "You must prove three things on the balance of probabilities: that the healthcare provider owed you a duty of care, that their treatment fell below the standard of a reasonably competent practitioner (breach), and that the breach caused you avoidable harm (causation)." },
    { question: "What standard of care is a doctor expected to meet in Scotland?", answer: "The legal test in Scotland is whether the clinician's conduct was supported by a responsible body of medical opinion — the Bolam/Hunter v Hanley standard. However, that body of opinion must itself withstand logical scrutiny. A clinician cannot simply rely on colleague endorsement if the approach is not defensible." },
    { question: "How do I prove my doctor caused my injury rather than my underlying condition?", answer: "This is the causation question, often the hardest part of a medical negligence claim. You need independent expert medical evidence explaining what would have happened with correct treatment versus what actually happened. The breach must materially cause or worsen your outcome." },
    { question: "Do I need an expert witness to make a medical negligence claim?", answer: "Almost always yes. Scottish courts require independent expert medical evidence to establish both the standard of care and causation. Your adviser will instruct appropriate specialists — often a clinician in the same field as the treating practitioner." },
    { question: "How long do I have to make a medical negligence claim in Scotland?", answer: "Three years from the date of the negligent treatment or, if later, the date you first knew that negligence may have caused your harm. This date of knowledge can be complex to establish — seek specialist advice if you are unsure when your time limit runs from." },
    { question: "Does a failed operation automatically mean negligence?", answer: "No. A poor outcome or complication is not in itself negligence. Medicine involves inherent risks that may materialise despite competent treatment. Negligence requires a breach of the required standard of care, not simply an outcome that was worse than hoped." },
  ],

  "nhs-negligence-claims-scotland-explained": [
    { question: "How do I make a medical negligence claim against NHS Scotland?", answer: "NHS Scotland clinical negligence claims are handled by the Central Legal Office (CLO) on behalf of NHS boards. Your claim is submitted to the CLO, which investigates and negotiates on behalf of the relevant board. The legal process and evidence requirements are the same as for any medical negligence claim." },
    { question: "Do I need to complain to the NHS before making a legal claim?", answer: "No. An NHS complaint and a legal claim are separate processes. A complaint may gather useful information and documents, but it is not a legal prerequisite. Be aware that complaint correspondence can sometimes be used in litigation, so seek advice before using the complaint process strategically." },
    { question: "Can I claim against the NHS and a private healthcare provider?", answer: "You can pursue claims against multiple defendants if more than one provider contributed to your harm. Private treatment carried out alongside NHS care may give rise to separate obligations. Identify all responsible parties at the outset." },
    { question: "How long do NHS Scotland clinical negligence claims take?", answer: "Straightforward claims where the CLO accepts liability may resolve in 12 to 18 months. Disputed cases, or those involving serious complex injuries, routinely take three to five years or longer. Expert evidence gathering is a major factor in the timeline." },
    { question: "What compensation can I receive from a successful NHS negligence claim?", answer: "Compensation can cover general damages (pain, suffering, loss of amenity), past and future earnings loss, costs of care and treatment, the difference between NHS and private provision where clinically justified, and other proven losses attributable to the negligence." },
    { question: "Will the NHS try to fight my negligence claim?", answer: "The CLO will investigate and may contest liability or causation if the evidence does not clearly support your claim. If the case is strong, the CLO will often negotiate a settlement. If it is disputed, independent expert evidence and potentially court proceedings will be needed." },
  ],

  "gp-negligence-claims-scotland": [
    { question: "Can I sue my GP in Scotland?", answer: "Yes. A GP owes a duty of care to their patients. If they fail to meet the standard of a reasonably competent general practitioner and that failure causes avoidable harm, a claim may be brought against the GP and their employing or contracting NHS board." },
    { question: "What are the most common GP negligence claims in Scotland?", answer: "Common categories include failure to diagnose a serious condition, delay in referral, prescribing the wrong medication or dose, failure to act on abnormal test results, and inadequate follow-up after a consultation." },
    { question: "How do I prove my GP made a negligent mistake?", answer: "You need independent expert evidence from a GP or relevant specialist confirming that the conduct fell below the required standard and that this caused your harm. Medical records documenting the consultation and subsequent events are central to the analysis." },
    { question: "What if my GP diagnosed me with the wrong condition?", answer: "A misdiagnosis is not automatically negligence. The question is whether a reasonably competent GP would have reached the correct diagnosis, or ordered investigations that would have led to it, with the information available at that consultation. Hindsight does not set the standard." },
    { question: "How long do I have to make a GP negligence claim in Scotland?", answer: "Three years from the date of the negligent consultation or the date you first knew that negligence may have caused your harm. Date of knowledge can be many years after the original event, particularly in delayed diagnosis cases. Seek advice as soon as you suspect negligence." },
    { question: "Can I claim if the GP's error worsened an existing condition?", answer: "Yes. The claim covers the avoidable deterioration or additional harm caused by the negligence, compared with the outcome with correct treatment. You are not required to prove you would have been entirely healthy — just that you would have been in a better position." },
  ],

  "birth-injury-claims-scotland": [
    { question: "Can I claim compensation for a birth injury in Scotland?", answer: "Yes. Birth injury claims arise where negligent care during pregnancy, labour or delivery causes avoidable harm to the mother or child. These are among the most complex and high-value personal injury claims, requiring specialist obstetric and midwifery expert evidence." },
    { question: "Who can make a birth injury claim — the mother or the child?", answer: "Both may have separate claims. The mother claims for her own injuries. A child can claim for their own injuries, normally through a parent acting on their behalf until the child reaches 16. The child's limitation period does not begin until their sixteenth birthday." },
    { question: "What causes of action arise in birth injury cases?", answer: "Common allegations include failure to monitor foetal distress, delay in performing an emergency caesarean section, mismanagement of shoulder dystocia, hypoxic-ischaemic encephalopathy (HIE), erb's palsy caused by excessive traction, and failure to identify or manage maternal conditions." },
    { question: "How long do I have to make a birth injury claim in Scotland?", answer: "For the mother, three years from the date of injury or knowledge. For the child, three years from their sixteenth birthday — meaning claims can generally be brought until age 19. However, evidence deteriorates with time, so early investigation protects the quality of the case." },
    { question: "How much compensation is awarded for cerebral palsy or serious birth injury?", answer: "Serious birth injury claims — particularly those involving cerebral palsy, brain damage or permanent disability — can result in very large awards reflecting lifetime care, equipment, housing adaptations, lost earnings and pain and suffering. Each case is assessed individually on its medical and financial evidence." },
    { question: "Does the NHS usually fight birth injury claims?", answer: "The CLO (Central Legal Office) investigates on behalf of NHS Scotland. Complex cases are often contested. Independent obstetric, midwifery and neonatal expert evidence is needed, and cases frequently take several years to resolve where liability and causation are disputed." },
  ],

  "cancer-misdiagnosis-claims-scotland": [
    { question: "Can I claim if my cancer was diagnosed late in Scotland?", answer: "Yes, if the delayed diagnosis was caused by a failure to meet the standard of a reasonably competent clinician, and the delay caused you avoidable harm — typically a worse prognosis, more aggressive treatment or reduced life expectancy." },
    { question: "What types of cancer misdiagnosis cases arise in Scotland?", answer: "Common categories include failure to refer after a suspicious presentation, delayed radiological or pathological reporting, overlooked abnormal blood results, misinterpretation of scans or biopsies, and failure to follow up when symptoms persist." },
    { question: "Do I have to prove that the cancer would have been cured with earlier diagnosis?", answer: "No. You must prove that earlier diagnosis would have given you a materially better outcome — which may mean less aggressive treatment, better survival statistics or avoidance of a specific complication. A claim does not require certainty of cure, only proof of avoidable worsening." },
    { question: "How is causation assessed in a cancer delay claim?", answer: "Oncology and relevant specialty experts compare the stage or extent of the cancer at the time of actual diagnosis with the likely stage at the time it should have been diagnosed. Statistics, staging evidence and the cancer's natural history inform the comparison." },
    { question: "How long do I have to claim for cancer misdiagnosis in Scotland?", answer: "Three years from the date of the negligent act or the date of knowledge. In late diagnosis cases, the date of knowledge is often the date you learned that earlier diagnosis was possible and that negligence may have contributed — which may be well after the original consultation." },
    { question: "Can the family of someone who died from cancer that was misdiagnosed make a claim?", answer: "Yes. Under the Damages (Scotland) Act 2011, qualifying relatives can claim for loss of society, financial dependency and grief. The executor can claim for the deceased's pre-death losses. A three-year period runs from the date of death or date of knowledge." },
  ],

  "care-home-negligence-claims-scotland": [
    { question: "Can I make a claim if a family member was harmed in a care home in Scotland?", answer: "Yes. Care homes have a duty of care to residents, regulated by the Care Inspectorate in Scotland. Where negligent care causes injury, illness or death, a claim may be brought against the care home operator." },
    { question: "What types of negligence occur in care homes?", answer: "Common categories include pressure ulcers (bedsores) caused by inadequate repositioning, falls due to inadequate supervision or risk assessment, medication errors, malnutrition or dehydration, failure to seek timely medical attention, and inadequate manual handling." },
    { question: "Who makes the claim if the care home resident lacks mental capacity?", answer: "A family member with power of attorney or a court-appointed guardian can act on behalf of an adult who lacks capacity. If no formal arrangement exists, a solicitor can advise on applying for the appropriate powers under Scottish adults with incapacity legislation." },
    { question: "Can I get care home records to support a claim?", answer: "Yes. You are entitled to request the resident's care records, medication administration records, risk assessments and incident reports. Your adviser can obtain these formally. The Care Inspectorate's inspection reports for the care home may also be relevant evidence." },
    { question: "How long do I have to make a care home negligence claim in Scotland?", answer: "Three years from the date of the injury or death, or from the date of knowledge. For a deceased resident, three years from the date of death or date of knowledge of the connection between the care and the death." },
    { question: "What compensation can be recovered for care home negligence?", answer: "Compensation can cover pain and suffering, the cost of additional care or treatment needed as a result of the negligence, financial losses, and in fatal cases the grief and loss of society experienced by qualifying relatives." },
  ],

  "prescription-error-claims-scotland": [
    { question: "Can I claim if I was given the wrong medication or dose in Scotland?", answer: "Yes. Prescribing errors by a GP or hospital doctor, and dispensing errors by a pharmacist, can ground a medical negligence claim where the error causes avoidable harm. Both the prescriber and the dispenser have independent duties of care." },
    { question: "What is the difference between a prescribing error and a dispensing error?", answer: "A prescribing error is made by the doctor writing or authorising the wrong drug, wrong dose, wrong route or failing to account for contraindications. A dispensing error is made by the pharmacist issuing the wrong drug or dose against the prescription. Both can independently ground a claim." },
    { question: "What harm can a prescription error cause?", answer: "Prescription errors can cause allergic reactions, toxic effects from overdose, under-treatment of a serious condition, dangerous drug interactions, organ damage, psychological harm and in serious cases death. The severity of harm determines the value of a claim." },
    { question: "How do I prove a prescription error harmed me?", answer: "You need medical records showing the error, the medication dispensed and your adverse reaction or under-treatment. Independent pharmacy or medical expert evidence is required to establish the standard of care and causation between the error and your specific harm." },
    { question: "Can I claim if a pharmacist dispensed the wrong drug?", answer: "Yes. A pharmacist has an independent professional duty to dispense correctly and to check prescriptions for obvious errors or contraindications. Where a dispensing error causes harm, the pharmacy and its owners may be liable." },
    { question: "How long do I have to make a prescription error claim in Scotland?", answer: "Three years from the date of the error or date of knowledge. If you suffered harm that only became apparent later — for example, long-term damage from prolonged incorrect medication — the date of knowledge may be later than the date of the error." },
  ],

  "industrial-disease-delayed-symptoms-scotland": [
    { question: "Can I claim for an industrial disease even if I was exposed to the risk many years ago?", answer: "Yes. In industrial disease cases the three-year time limit runs from the date of diagnosis or from the date you first knew your condition was caused by your work — not from the date of exposure. Exposures decades in the past can still ground valid claims." },
    { question: "What is the date of knowledge in an industrial disease claim?", answer: "The date of knowledge is the date when you first knew, or ought reasonably to have known, that your condition was significant and that it was caused by your working conditions. Establishing this date correctly is crucial because the three-year limitation period starts from that point." },
    { question: "My employer no longer exists — can I still claim?", answer: "Possibly. Employers must have held employers' liability insurance. Insurance records may still be traceable through the Employers' Liability Tracing Office (ELTO). Successor companies or insurers may remain liable. Specialist advice is essential in historical employer cases." },
    { question: "What industrial diseases can I claim for in Scotland?", answer: "Common industrial disease claims include asbestosis, mesothelioma, asbestos-related lung cancer, noise-induced hearing loss, vibration white finger (HAVS), occupational asthma, dermatitis, pneumoconiosis and repetitive strain injuries caused by working conditions." },
    { question: "How do I prove what I was exposed to at work decades ago?", answer: "Evidence can include employment records, wage slips, trade union records, former colleagues' statements, HSE enforcement records, medical research on specific industries, and site or process records. Specialist evidence-gathering is usually required for historical claims." },
    { question: "How long does an industrial disease claim take in Scotland?", answer: "Industrial disease claims are often complex and can take two to five years or more, depending on the age and complexity of the employment history, the number of defendants and the medical evidence required. Interim payments may be available in appropriate cases where a claimant's health is deteriorating." },
  ],

  "asbestos-claims-scotland": [
    { question: "Can I make an asbestos claim in Scotland?", answer: "Yes. Scotland has high rates of asbestos-related disease, particularly from shipbuilding, construction and manufacturing. Claims for mesothelioma, asbestosis, asbestos-related lung cancer and pleural thickening are well established in Scottish law." },
    { question: "What diseases can be caused by asbestos exposure?", answer: "Asbestos exposure can cause mesothelioma (cancer of the lining of the lungs or abdomen), lung cancer, asbestosis (scarring of lung tissue), pleural plaques, pleural thickening and pleural effusion. Mesothelioma is almost always caused by asbestos and carries the most urgent legal time limit." },
    { question: "Is there a compensation scheme for mesothelioma if my employer cannot be traced?", answer: "Yes. The Mesothelioma Act 2014 established the Diffuse Mesothelioma Payment Scheme (DMPS) for those who cannot trace their employer or insurer. Payments are made as a percentage of average court awards. Specialist advice is needed to access this scheme." },
    { question: "What if my employer went out of business before my diagnosis?", answer: "Employers must have held employers' liability insurance. The Employers' Liability Tracing Office (ELTO) maintains a database to trace historic policies. Even if the employer is dissolved, the insurer may still be traceable and liable. Seek specialist asbestos claims advice." },
    { question: "How long do I have to make an asbestos claim in Scotland?", answer: "Three years from the date of diagnosis or date of knowledge. For mesothelioma, given the urgency of the condition, seek legal advice as soon as possible after diagnosis. Interim payments may be available quickly where liability is clear." },
    { question: "Can relatives claim after someone dies from an asbestos disease?", answer: "Yes. Under the Damages (Scotland) Act 2011, qualifying relatives can claim for loss of society, financial dependency and grief. The executor can claim for the deceased's pre-death losses and pain. A three-year period runs from the date of death or knowledge." },
  ],

  "noise-induced-hearing-loss-claims-scotland": [
    { question: "Can I claim for industrial deafness caused by my job in Scotland?", answer: "Yes. Noise-induced hearing loss (NIHL) caused by excessive noise at work is a recognised industrial disease. You can claim against any employer responsible for the noise exposure, even decades after the exposure occurred." },
    { question: "How loud does noise need to be to cause a claim?", answer: "Under the Control of Noise at Work Regulations 2005, employers must take action at exposure levels of 80dB(A) and must provide hearing protection and implement controls at 85dB(A). Sustained exposure above these levels without adequate protection can ground a claim." },
    { question: "How do I prove my hearing loss was caused by my work?", answer: "An audiologist or ENT specialist conducts hearing tests and provides a report analysing whether the pattern of hearing loss is consistent with noise exposure rather than age-related hearing loss. An occupational hygienist may assess historic noise levels at your workplace." },
    { question: "Can I claim if I also have age-related hearing loss?", answer: "Yes. The claim covers the proportion of hearing loss attributable to the noise exposure rather than natural ageing. An independent expert will separate the two causes. You are not required to show the noise caused all of your hearing loss." },
    { question: "What if I worked for many employers with excessive noise?", answer: "Each employer responsible for the damaging exposure may be a defendant. In practice, insurers may apportion liability between employers based on the duration and intensity of exposure at each. Specialist advice helps identify the relevant defendants and their insurers." },
    { question: "How long do I have to claim for industrial hearing loss in Scotland?", answer: "Three years from the date of diagnosis or the date you first knew your hearing loss was work-related. For many people, this is the date of an audiology report confirming the occupational cause. Seek advice promptly after receiving such a report." },
  ],

  "vibration-white-finger-claims-scotland": [
    { question: "What is vibration white finger and can I claim compensation in Scotland?", answer: "Vibration white finger (VWF), or hand-arm vibration syndrome (HAVS), is a condition caused by prolonged use of vibrating tools or machinery. Symptoms include whitening or numbness of the fingers, reduced grip and vascular and neurological damage. It is a recognised industrial disease and a common basis for claims in Scotland." },
    { question: "What jobs can cause vibration white finger?", answer: "HAVS commonly affects workers using angle grinders, chainsaws, pneumatic drills, jackhammers, needle guns, and similar vibrating tools. It is prevalent in construction, mining, oil and gas, engineering, shipbuilding and forestry industries — all prominent in Scotland." },
    { question: "How is HAVS diagnosed?", answer: "HAVS is diagnosed through a clinical examination and standardised tests of finger circulation and sensation. The severity is graded using the Stockholm Workshop Scale. An occupational physician or specialist in occupational medicine typically carries out the assessment for legal purposes." },
    { question: "Can I claim if my employer provided gloves and reduced vibration exposure?", answer: "It depends on when the measures were introduced, their adequacy and what the employer knew. Compliance with exposure limits reduces but does not automatically prevent liability for exposure that occurred before controls were adequate. Each case is assessed on its specific facts and timeline." },
    { question: "What compensation can I receive for HAVS in Scotland?", answer: "Compensation covers pain, suffering and loss of amenity, loss of earnings, the cost of adapting to reduced hand function, and any future losses. Serious HAVS can cause permanent disability affecting grip, dexterity and cold tolerance, which significantly increases the value of a claim." },
    { question: "How long do I have to claim for vibration white finger in Scotland?", answer: "Three years from the date of diagnosis or date of knowledge — whichever is later. As symptoms often develop gradually, seek medical assessment and legal advice as soon as you notice persistent symptoms, rather than waiting for a formal diagnosis." },
  ],

  "what-is-my-accident-claim-worth-scotland": [
    { question: "How is personal injury compensation calculated in Scotland?", answer: "Compensation has two components: general damages (pain, suffering and loss of amenity), valued by reference to comparable Scottish or UK court awards and the Judicial College Guidelines; and special damages (your actual financial losses such as lost earnings, treatment costs and care), which are calculated from evidence." },
    { question: "How much is a whiplash claim worth in Scotland?", answer: "Whiplash awards in Scotland depend on symptom severity and duration, effect on daily life and any financial losses. They are not fixed by a tariff. Mild whiplash resolving within a few months attracts lower awards; severe or persistent symptoms with significant financial consequences attract much more." },
    { question: "Can I include future losses in my claim?", answer: "Yes. Future loss of earnings, future care costs, future treatment and future equipment or accommodation needs can all be claimed where supported by medical evidence and properly quantified. Future loss calculations often require expert evidence from medical, care and employment specialists." },
    { question: "How are care costs claimed if a family member looks after me?", answer: "The cost of care provided gratuitously by family or friends is a recognised head of loss in Scotland. Keep a detailed record of the care provided — hours, tasks and the effect on the carer — from the date of the accident. Expert care evidence may be needed for serious injuries." },
    { question: "Does an insurer's first offer reflect what my claim is worth?", answer: "Not necessarily. Early offers are sometimes made before full medical evidence is available and may not reflect the true value of your losses. A full-and-final settlement agreed before prognosis is established can significantly undervalue a claim if symptoms worsen." },
    { question: "What tools exist for estimating compensation in Scotland?", answer: "The Judicial College Guidelines provide ranges for common injury types used by Scottish courts. Scottish court decisions (reported in SCLR, SLT and elsewhere) also provide comparators. Online calculators provide rough estimates only — the real value depends on your specific medical and financial evidence." },
  ],

  "no-win-no-fee-scotland-explained": [
    { question: "What does no win, no fee mean in Scotland?", answer: "No win, no fee means that if your claim is unsuccessful, you do not pay your solicitor's fees. If your claim succeeds, a payment — called a success fee — may be deducted from your compensation. The amount is set out in your written agreement before you proceed." },
    { question: "Is there a risk I will have to pay anything if I lose?", answer: "Under a properly structured Scottish no-win-no-fee agreement, you should not pay your solicitor's base fee if you lose. However, there may still be disbursements such as expert report fees or court costs. Ask your adviser to explain in writing exactly what you would be liable for if the claim is unsuccessful." },
    { question: "What is a success fee in Scotland?", answer: "A success fee is a percentage of your compensation retained by your solicitor as part of the no-win-no-fee arrangement. The Civil Litigation (Expenses and Group Proceedings) (Scotland) Act 2018 regulates success fees in Scotland, including caps on the percentage that can be charged." },
    { question: "Do I need after-the-event insurance for a no-win-no-fee claim in Scotland?", answer: "After-the-event (ATE) insurance can protect you against an opponent's legal costs if the claim fails. Whether it is needed and who pays for it depends on your specific funding arrangement. Ask your adviser to explain the position clearly before you proceed." },
    { question: "Can I get a no-win-no-fee agreement for any type of claim in Scotland?", answer: "No-win-no-fee arrangements are commonly available for personal injury, road accident and clinical negligence claims in Scotland. Whether a specific solicitor will take your case on this basis depends on the merits of the claim, not just its type." },
    { question: "What should I check before signing a no-win-no-fee agreement in Scotland?", answer: "Confirm exactly what costs you bear if you win, what (if any) you bear if you lose, the success fee percentage and any cap, how disbursements are funded, and what happens if you change solicitor mid-claim. Ask for all of this in plain writing before signing." },
  ],

  "serious-injury-rehabilitation-scotland": [
    { question: "What is serious injury rehabilitation and how does it help a claim?", answer: "Rehabilitation — medical, physical, psychological and vocational — improves the injured person's outcome and is also relevant to the claim because evidence of genuine need and its cost forms a significant part of serious injury compensation. Early rehabilitation may be funded by an insurer under a rehabilitation agreement." },
    { question: "Can I get interim payments to fund rehabilitation while my claim is ongoing?", answer: "Yes, in appropriate cases where liability is reasonably established. Interim payments from the at-fault insurer can fund private rehabilitation, care, equipment and accommodation adaptations before final settlement. Applications should be supported by evidence of clinical need and cost." },
    { question: "What types of rehabilitation might I need after a serious injury?", answer: "Serious injuries may require neurological rehabilitation, physiotherapy, occupational therapy, speech and language therapy, clinical psychology, pain management, vocational rehabilitation and specialist social care support. The appropriate disciplines depend on the nature and consequences of the injury." },
    { question: "Will the insurer fund my rehabilitation?", answer: "Where liability is sufficiently clear, many insurers will agree to fund rehabilitation under the Rehabilitation Code or a bespoke arrangement, as this often improves outcomes and may reduce final settlement costs. A case manager may be appointed to coordinate the programme." },
    { question: "How is care provided by family members valued in a serious injury claim?", answer: "Gratuitous care provided by family members is a recognised head of loss. Keep a detailed record of all care and assistance from the date of injury, noting hours, tasks and the carer's own losses. This care is valued at a reasonable hourly rate, typically below the commercial care rate." },
    { question: "Should I accept a settlement offer before my rehabilitation is complete?", answer: "Generally not. A settlement before rehabilitation is complete, and before prognosis is established, risks significantly undervaluing long-term care, future earnings and ongoing treatment costs. Your adviser should advise against settling until the medical picture is sufficiently stable to assess future needs reliably." },
  ],

  "fatal-accident-compensation-scotland": [
    { question: "Who can claim compensation after a fatal accident in Scotland?", answer: "The deceased's executor can claim for losses the deceased suffered before death. Qualifying relatives — including a spouse, civil partner, children, parents and certain others — can claim under the Damages (Scotland) Act 2011 for loss of society, financial dependency and grief." },
    { question: "What is loss of society in a Scottish fatal accident claim?", answer: "Loss of society is compensation for the loss of the care, guidance, companionship and love of the deceased. It is a distinct head of loss under Scots law and may be claimed by qualifying relatives even where there is no financial dependency." },
    { question: "Do I need a criminal conviction to make a civil compensation claim after a fatal accident?", answer: "No. A civil claim for damages and a criminal prosecution are entirely separate. A civil claim can succeed on the civil standard of proof (balance of probabilities) even where no criminal charge is brought, or where a criminal charge fails." },
    { question: "What is a Fatal Accident Inquiry and how does it relate to compensation?", answer: "A Fatal Accident Inquiry (FAI) is a Scottish public inquiry to establish the circumstances of certain deaths. It does not award compensation. Its findings may be used as evidence in a civil damages action, but it has a different legal function and a civil claim should not wait for FAI conclusions." },
    { question: "How long do relatives have to claim after a fatal accident in Scotland?", answer: "Three years from the date of death or the date on which a relative first had knowledge that the death was caused by another party's fault. Do not allow criminal proceedings or public inquiries to allow the civil time limit to expire — seek civil advice promptly." },
    { question: "What financial losses can be included in a fatal accident claim?", answer: "Claims can include the deceased's pre-death pain and suffering, lost financial support (income, pension, household services), loss of society for qualifying relatives, travel and funeral expenses, and the cost of dependency support for a child. Evidence of the deceased's income, expenses and contributions is essential." },
  ],

  "slip-trip-fall-claims-scotland": [
    { question: "Can I claim for a slip, trip or fall in Scotland?", answer: "Yes, if the accident was caused by a hazard that the occupier of the premises knew about or should have found through reasonable inspection, and failed to address. The Occupiers' Liability (Scotland) Act 1960 imposes a duty of reasonable care on those who control premises." },
    { question: "What do I need to prove for a slip claim in Scotland?", answer: "You must show that a hazard existed (such as a wet floor, loose surface or obstructed walkway), that the occupier knew or should have known about it, and that it caused your fall and injury. Evidence of the hazard at the time of the accident and inspection records are key." },
    { question: "Do I have a claim if there was a wet floor sign?", answer: "A warning sign reduces but does not necessarily eliminate liability. The question is whether the occupier took all reasonable steps to make the area safe. If a sign alone was insufficient — for example, the hazard could have been removed or the area closed — a claim may still succeed." },
    { question: "How long do I have to claim for a slip, trip or fall in Scotland?", answer: "Three years from the date of the accident or date of knowledge. CCTV evidence is often overwritten within days. Report the accident in the premises accident book and photograph the hazard immediately while it is still present." },
    { question: "What evidence should I gather after a slip or fall?", answer: "Report the incident to the premises manager immediately and get an accident book entry. Photograph the hazard, your footwear and the scene. Obtain witness details. Retain your clothing and footwear. Seek medical treatment and record all symptoms from the outset." },
    { question: "Can I claim for a fall on a public pavement or street in Scotland?", answer: "Yes, if the fall was caused by a defect in the pavement that the roads or local authority knew about or should have found through inspection. The relevant authority must have an opportunity to repair the defect — a brand-new defect that was never reported may not ground a claim." },
  ],

  "supermarket-accident-claims-scotland": [
    { question: "Can I claim if I slipped or fell in a supermarket in Scotland?", answer: "Yes. Supermarkets owe a duty of care to customers under the Occupiers' Liability (Scotland) Act 1960. If you were injured because of a wet floor, spillage, loose flooring, falling stock or other hazard that should have been identified and addressed, you may have a valid claim." },
    { question: "What if there was a cleaning schedule — does that protect the supermarket from liability?", answer: "A cleaning schedule is evidence of a system, but it must be actually followed and appropriate for the risk. If a spillage occurred between inspections and was obviously present for long enough to be found and dealt with, a schedule alone does not prevent liability." },
    { question: "How do I prove when a spillage happened?", answer: "Crucial evidence includes CCTV footage, inspection log entries showing the last check of that area, staff testimony and witness accounts of how long the spillage had been present. Request CCTV preservation immediately — most systems overwrite within 24 to 72 hours." },
    { question: "What should I do immediately after a supermarket accident?", answer: "Report the incident to the store manager and ensure an accident book entry is made. Photograph the hazard and your injuries before it is cleaned up or removed. Obtain witness details, seek medical treatment promptly, and keep your footwear in case it becomes relevant." },
    { question: "Can I claim if I was injured by a falling product in a supermarket?", answer: "Yes. Supermarkets must stack products safely and at appropriate heights. If a product falls due to unstable stacking, damage or an overfull shelf and injures a customer, the supermarket may be liable. Photograph the scene immediately and report to staff." },
    { question: "How long do I have to claim for a supermarket accident in Scotland?", answer: "Three years from the date of the accident or date of knowledge. Evidence deteriorates quickly and CCTV is overwritten fast, so report promptly and seek advice as soon as possible after the incident." },
  ],

  "council-pavement-trip-claims-scotland": [
    { question: "Can I claim against the council for a pavement trip in Scotland?", answer: "Yes. Local councils have a statutory duty to maintain public pavements under the Roads (Scotland) Act 1984. If a defect in the pavement caused your fall and the council knew or should have known about it, a claim may be made against the council." },
    { question: "How bad does a pavement defect need to be for a successful claim?", answer: "There is no fixed measurement that automatically creates liability, but councils use intervention criteria (often 20–25mm for vertical displacement) to decide when to repair. Even if a defect is below a council's threshold, a claim may succeed if the hazard was clearly dangerous in context — poor lighting, narrow pavement, or high pedestrian use." },
    { question: "What if the council says they repaired the pavement before the accident?", answer: "Previous repairs and the inspection regime are relevant evidence. If a defect reappeared after a repair and the council had not re-inspected, this may still ground a claim. Records of past reports, repairs and inspections can be obtained from the council." },
    { question: "What evidence should I gather after a pavement trip in Scotland?", answer: "Photograph the defect with a scale object and from different angles before it is repaired. Record the exact location, time and conditions. Obtain witness details. Report the defect to the council in writing and keep a copy. Seek medical attention and photograph your injuries." },
    { question: "How long do I have to make a council pavement trip claim in Scotland?", answer: "Three years from the date of the accident or date of knowledge. Defects are often repaired quickly after a claim is reported. Photograph and measure the defect as soon as safely possible." },
    { question: "What compensation can I get for a pavement trip injury?", answer: "Compensation can include general damages for pain, suffering and loss of amenity, and special damages for lost earnings, medical and treatment costs, care provided by others, and other financial losses caused by the injury. The amount depends on the severity and duration of your injuries." },
  ],

};

export function getGuideFaqs(slug: string): FaqItem[] {
  return guideFaqs[slug] ?? [];
}
